options.getOption:
if (!context.panel.data?.series?.length) {
  return { xAxis: { type: "time" }, yAxis: { type: "value" }, series: [] };
}

let timeData = [];
let inlet = [];

const toArray = (v) =>
  Array.isArray(v) ? v : (v?.toArray ? v.toArray() : Array.from(v ?? []));

const toMs = (t) => {
  if (t == null) return null;
  if (typeof t === "number") return t;
  const d = t instanceof Date ? t : new Date(t);
  const ms = d.getTime();
  return Number.isFinite(ms) ? ms : null;
};

// Pull Time + Inlet safely
context.panel.data.series.forEach((s) => {
  const tf = s.fields.find((f) => f.type === "time" || f.name === "Time");
  if (tf?.values && !timeData.length) timeData = toArray(tf.values).map(toMs);

  const inletField = s.fields.find(
    (f) => f.name === "Inlet" || f.config?.displayNameFromDS === "Inlet"
  );
  if (s.refId === "Inlet" && inletField?.values) inlet = toArray(inletField.values);
});

const HOUR_MS = 60 * 60 * 1000;
// Shift x-values by -30min so UTC hour ticks land on IST HH:00
const SHIFT_MS = 30 * 60 * 1000;

const inletSeries = timeData
  .filter((t) => t != null)
  .map((t, i) => [
    t - SHIFT_MS,
    inlet[i] == null || inlet[i] <= 0 ? null : Math.round(inlet[i]),
  ]);

return {
  backgroundColor: "transparent",

  tooltip: {
    trigger: "axis",
    axisPointer: { type: "shadow" },
    formatter: function (params) {
      const shiftedMs = params?.[0]?.value?.[0];
      const ts = shiftedMs
        ? new Intl.DateTimeFormat("en-US", {
          timeZone: "Asia/Kolkata",
          year: "numeric",
          month: "2-digit",
          day: "2-digit",
          hour: "2-digit",
          minute: "2-digit",
          hour12: false,
        }).format(new Date(shiftedMs))
        : "";

      let tooltipText = `${ts}<br/>`;
      params.forEach((item) => {
        const v = item?.value?.[1];
        const valueText = v == null ? "-" : `${v} m³`;
        tooltipText += `${item.marker} ${item.seriesName}: ${valueText}<br/>`;
      });
      return tooltipText;
    },
  },

  legend: { data: ["Raw Biogas Production"] },

  grid: { left: "5%", right: "4%", bottom: "12%", containLabel: true },

  xAxis: {
    type: "time",
    minInterval: HOUR_MS,
    maxInterval: HOUR_MS,
    axisTick: { show: true },
    splitLine: { show: true },
    axisLabel: {
      rotate: 45,
      formatter: function (shiftedValue) {
        return new Intl.DateTimeFormat("en-US", {
          timeZone: "Asia/Kolkata",
          month: "2-digit",
          day: "2-digit",
          hour: "2-digit",
          minute: "2-digit",
          hour12: false,
        }).format(new Date(shiftedValue));
      },
    },
  },

  yAxis: {
    type: "value",
    axisLabel: { formatter: (val) => `${val} m³` },
    splitLine: { lineStyle: { type: "dashed", opacity: 0.3 } },
  },

  series: [
    {
      name: "Raw Biogas Production",
      type: "bar",
      data: inletSeries,
      itemStyle: { opacity: 0.85 },

      // ✅ labels on top of each bar
      label: {
        show: true,
        position: "top",
        formatter: (p) => {
          const v = p?.value?.[1];
          return v == null ? "" : `${v}`;
        },
      },
    },
  ],
};

