options.getOption:
if (!context.panel.data?.series?.length) {
  return { xAxis: { type: "time" }, yAxis: { type: "value" }, series: [] };
}

const toArray = (v) =>
  Array.isArray(v) ? v : (v?.toArray ? v.toArray() : Array.from(v ?? []));

const findField = (s, wanted) =>
  s.fields.find(
    (f) =>
      f.name === wanted ||
      f.config?.displayNameFromDS === wanted ||
      f.config?.displayName === wanted
  );

const toMs = (t) => {
  if (t == null) return null;
  if (typeof t === "number") return t;
  const d = t instanceof Date ? t : new Date(t);
  const ms = d.getTime();
  return Number.isFinite(ms) ? ms : null;
};

function extractSeries(wantedFieldName) {
  for (const s of context.panel.data.series) {
    const tf = s.fields.find((f) => f.type === "time" || f.name === "Time");
    const vf = findField(s, wantedFieldName);
    if (tf?.values && vf?.values) {
      return {
        time: toArray(tf.values).map(toMs).filter((x) => x != null),
        values: toArray(vf.values),
      };
    }
  }
  return { time: [], values: [] };
}

// === Hourly fields (your aliases) ===
const s01 = extractSeries("Hourly Flow FIT 600-01");
const s02 = extractSeries("Hourly Flow FIT 600-02");
const st = extractSeries("Total"); // optional; may be empty

// Union of timestamps
const allTimes = Array.from(new Set([...(s01.time || []), ...(s02.time || []), ...(st.time || [])]))
  .sort((a, b) => a - b);

// Map timestamp -> value
const mapByTime = (timeArr, valArr) => {
  const m = new Map();
  for (let i = 0; i < (timeArr?.length || 0); i++) {
    m.set(timeArr[i], valArr[i]);
  }
  return m;
};

const m01 = mapByTime(s01.time, s01.values);
const m02 = mapByTime(s02.time, s02.values);
const mt = mapByTime(st.time, st.values);

const HOUR_MS = 60 * 60 * 1000;
// Shift x-values by -30min so UTC hour ticks land on IST HH:00
const SHIFT_MS = 30 * 60 * 1000;

// Build [time,value] pairs with shifted time
const fit600_01 = allTimes.map((t) => {
  const v = Number(m01.get(t)) || 0;
  return [t - SHIFT_MS, v <= 0 ? null : Math.round(v)];
});

const fit600_02 = allTimes.map((t) => {
  const v = Number(m02.get(t)) || 0;
  return [t - SHIFT_MS, v <= 0 ? null : Math.round(v)];
});

// Total label values aligned to allTimes
const total = allTimes.map((t) => {
  const v = mt.get(t);
  return v == null ? null : Number(v);
});

return {
  backgroundColor: "transparent",

  tooltip: {
    trigger: "axis",
    axisPointer: { type: "shadow" },
    formatter: function (params) {
      const shiftedMs = params?.[0]?.value?.[0];
      const ts = shiftedMs
        ? new Intl.DateTimeFormat("en-US", {
          timeZone: "Asia/Kolkata",
          year: "numeric",
          month: "2-digit",
          day: "2-digit",
          hour: "2-digit",
          minute: "2-digit",
          hour12: false,
        }).format(new Date(shiftedMs))
        : "";

      let out = `${ts}<br/>`;
      params.forEach((item) => {
        const v = item?.value?.[1];
        out += `${item.marker} ${item.seriesName}: ${v == null ? "-" : `${v} kg`}<br/>`;
      });
      return out;
    },
  },

  legend: { data: ["FIT 600-01", "FIT 600-02"] },

  grid: { left: "5%", right: "4%", bottom: "12%", containLabel: true },

  xAxis: {
    type: "time",
    minInterval: HOUR_MS,
    maxInterval: HOUR_MS,
    axisTick: { show: true },
    splitLine: { show: true },
    axisLabel: {
      rotate: 45,
      formatter: function (shiftedValue) {
        return new Intl.DateTimeFormat("en-US", {
          timeZone: "Asia/Kolkata",
          month: "2-digit",
          day: "2-digit",
          hour: "2-digit",
          minute: "2-digit",
          hour12: false,
        }).format(new Date(shiftedValue));
      },
    },
  },

  yAxis: {
    type: "value",
    // ✅ show units on y-axis ticks
    axisLabel: { formatter: (val) => `${val} kg` },
    splitLine: { lineStyle: { type: "dashed", opacity: 0.3 } },
  },

  series: [
    {
      name: "FIT 600-01",
      type: "bar",
      stack: "total",
      data: fit600_01,
      itemStyle: { opacity: 0.85 },
    },
    {
      name: "FIT 600-02",
      type: "bar",
      stack: "total",
      data: fit600_02,
      itemStyle: { opacity: 0.85 },
      label: {
        show: true,
        position: "top",
        formatter: (p) => {
          const t = total?.[p.dataIndex];
          return t == null ? "" : Math.round(t);
        },
      },
    },
  ],
};

